Function.prototype.myBind = function (thisArg, ...early) {
  const fn = this;
  return function (...later) {
    return fn.apply(thisArg, [...early, ...later]);
  };
};

function price(base, tax, tip) {
  return `${this.currency}${base + tax + tip}`;
}

const euro = { currency: "EUR " };
const withTax = price.myBind(euro, 10, 2);

console.log(withTax(1));
console.log(withTax.call({ currency: "USD " }, 5));
console.log(withTax.myBind({ currency: "GBP " }, 0)());
